   142→      open,
   143→      setOpen,
   144→      isMobile,
   145→      openMobile,
   146→      setOpenMobile,
   147→      toggleSidebar,
   148→    }),
   149→    [state, open, setOpen, isMobile, openMobile, setOpenMobile, toggleSidebar],
   150→  );
