/* Context-based theming for B2C and B2B interfaces */

/* B2C Theme - Emotional and warm */
.theme-b2c {
  /* Color variants for B2C */
  --blue-25: hsl(221, 100%, 97%);
  --orange-25: hsl(34, 100%, 97%);
  --red-25: hsl(350, 100%, 97%);
  --green-25: hsl(142, 100%, 97%);
  --purple-25: hsl(270, 100%, 97%);
  --yellow-25: hsl(45, 100%, 97%);
  --pink-25: hsl(320, 100%, 97%);

  /* B2C specific spacing and layout */
  --spacing-card: 1.5rem;
  --spacing-section: 2rem;
  --radius-card: 0.75rem;
  --shadow-card:
    0 4px 6px -1px rgb(0 0 0 / 0.1), 0 2px 4px -2px rgb(0 0 0 / 0.1);
}

/* B2B Theme - Professional and compact */
.theme-b2b {
  /* Color variants for B2B */
  --slate-25: hsl(210, 40%, 98%);
  --slate-150: hsl(210, 40%, 94%);
  --blue-25: hsl(215, 100%, 97%);
  --green-25: hsl(142, 100%, 97%);
  --yellow-25: hsl(45, 100%, 97%);
  --orange-25: hsl(34, 100%, 97%);
  --red-25: hsl(350, 100%, 97%);
  --indigo-25: hsl(225, 100%, 97%);

  /* B2B specific spacing and layout */
  --spacing-card: 1rem;
  --spacing-section: 1.5rem;
  --radius-card: 0.375rem;
  --shadow-card: 0 1px 3px 0 rgb(0 0 0 / 0.1), 0 1px 2px -1px rgb(0 0 0 / 0.1);
}

/* Responsive theme adjustments */
@media (max-width: 768px) {
  .theme-b2c {
    --spacing-card: 1rem;
    --spacing-section: 1.5rem;
  }

  .theme-b2b {
    --spacing-card: 0.75rem;
    --spacing-section: 1rem;
  }
}

/* Animation preferences based on context */
.theme-b2c * {
  transition-duration: 200ms;
}

.theme-b2b * {
  transition-duration: 150ms;
}

/* Font weight adjustments */
.theme-b2c h1,
.theme-b2c h2,
.theme-b2c h3 {
  font-weight: 600;
}

.theme-b2b h1,
.theme-b2b h2,
.theme-b2b h3 {
  font-weight: 700;
}

