@import "tailwindcss";

@plugin "@tailwindcss/typography";
@plugin "tailwindcss-animate";

/* Context-based theming for B2C and B2B interfaces */
@import "../src/styles/context-themes.css";
/* Animations */
@import "../src/styles/animations.css";

@custom-variant dark (&:is(.dark *));

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --font-sans: var(--font-geist-sans);
  --font-mono: var(--font-geist-mono);
  --color-sidebar-ring: var(--sidebar-ring);
  --color-sidebar-border: var(--sidebar-border);
  --color-sidebar-accent-foreground: var(--sidebar-accent-foreground);
  --color-sidebar-accent: var(--sidebar-accent);
  --color-sidebar-primary-foreground: var(--sidebar-primary-foreground);
  --color-sidebar-primary: var(--sidebar-primary);
  --color-sidebar-foreground: var(--sidebar-foreground);
  --color-sidebar: var(--sidebar);
  --color-chart-5: var(--chart-5);
  --color-chart-4: var(--chart-4);
  --color-chart-3: var(--chart-3);
  --color-chart-2: var(--chart-2);
  --color-chart-1: var(--chart-1);
  --color-ring: var(--ring);
  --color-input: var(--input);
  --color-border: var(--border);
  --color-destructive-foreground: var(--destructive-foreground);
  --color-destructive: var(--destructive);
  --color-accent-foreground: var(--accent-foreground);
  --color-accent: var(--accent);
  --color-muted-foreground: var(--muted-foreground);
  --color-muted: var(--muted);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-secondary: var(--secondary);
  --color-primary-foreground: var(--primary-foreground);
  --color-primary: var(--primary);
  --color-popover-foreground: var(--popover-foreground);
  --color-popover: var(--popover);
  --color-success-foreground: var(--success-foreground);
  --color-success: var(--success);
  --color-warning-foreground: var(--warning-foreground);
  --color-warning: var(--warning);
  --color-info-foreground: var(--info-foreground);
  --color-info: var(--info);
  --color-card-foreground: var(--card-foreground);
  --color-card: var(--card);
  --radius-sm: calc(var(--radius) - 4px);
  --radius-md: calc(var(--radius) - 2px);
  --radius-lg: var(--radius);
  --radius-xl: calc(var(--radius) + 4px);
  --radius-2xl: calc(var(--radius) + 8px);
  --radius-3xl: calc(var(--radius) + 16px);
  --animate-accordion-down: accordion-down 0.2s ease-out;
  --animate-accordion-up: accordion-up 0.2s ease-out;

  @keyframes accordion-down {
    from {
      height: 0;
    }
    to {
      height: var(--radix-accordion-content-height);
    }
  }

  @keyframes accordion-up {
    from {
      height: var(--radix-accordion-content-height);
    }
    to {
      height: 0;
    }
  }
}

/* ============================================
   DARK FIRST DESIGN SYSTEM - ChooseWisely
   ============================================ */

:root {
  /* Brand Colors - Dark First */
  --brand-deep: #050810;
  --brand-surface: #0d121f;
  --brand-elevated: #141b2d;
  --brand-accent: #34d399;
  --brand-highlight: #6366f1;
  --brand-danger: #f43f5e;

  /* Text Colors */
  --text-primary: #f8fafc;
  --text-secondary: #94a3b8;
  --text-muted: #64748b;

  /* Effects */
  --border-subtle: rgba(255, 255, 255, 0.06);
  --border-glass: rgba(255, 255, 255, 0.1);
  --glow-accent: rgba(52, 211, 153, 0.15);
  --glow-accent-strong: rgba(52, 211, 153, 0.3);
  --glow-highlight: rgba(99, 102, 241, 0.15);
  --glow-highlight-strong: rgba(99, 102, 241, 0.3);

  /* Glass morphism */
  --glass-bg: rgba(255, 255, 255, 0.03);
  --glass-bg-elevated: rgba(255, 255, 255, 0.05);
  --glass-border: rgba(255, 255, 255, 0.06);

  /* Dark First Colors (applied by default) */
  --background: var(--brand-deep);
  --foreground: var(--text-primary);
  --card: var(--brand-surface);
  --card-foreground: var(--text-primary);
  --popover: var(--brand-surface);
  --popover-foreground: var(--text-primary);
  --primary: var(--brand-accent);
  --primary-foreground: var(--brand-deep);
  --secondary: var(--brand-elevated);
  --secondary-foreground: var(--text-primary);
  --muted: var(--brand-elevated);
  --muted-foreground: var(--text-muted);
  --accent: var(--brand-highlight);
  --accent-foreground: var(--text-primary);
  --destructive: var(--brand-danger);
  --destructive-foreground: var(--text-primary);
  --border: var(--border-subtle);
  --input: var(--border-subtle);
  --ring: var(--brand-accent);

  /* Chart colors */
  --chart-1: var(--brand-accent);
  --chart-2: var(--brand-highlight);
  --chart-3: #a78bfa;
  --chart-4: #f472b6;
  --chart-5: #fbbf24;

  --radius: 0.75rem;

  /* Sidebar */
  --sidebar: var(--brand-surface);
  --sidebar-foreground: var(--text-primary);
  --sidebar-primary: var(--brand-accent);
  --sidebar-primary-foreground: var(--brand-deep);
  --sidebar-accent: var(--brand-elevated);
  --sidebar-accent-foreground: var(--text-primary);
  --sidebar-border: var(--border-subtle);
  --sidebar-ring: var(--brand-accent);

  /* Status colors */
  --success: #34d399;
  --success-foreground: var(--brand-deep);

  --warning: #fbbf24;
  --warning-foreground: var(--brand-deep);

  --info: var(--brand-highlight);
  --info-foreground: var(--text-primary);
}

/* Dark mode (default, reinforced) */
.dark {
  --background: var(--brand-deep);
  --foreground: var(--text-primary);
  --card: var(--brand-surface);
  --card-foreground: var(--text-primary);
  --popover: var(--brand-surface);
  --popover-foreground: var(--text-primary);
  --primary: var(--brand-accent);
  --primary-foreground: var(--brand-deep);
  --secondary: var(--brand-elevated);
  --secondary-foreground: var(--text-primary);
  --muted: var(--brand-elevated);
  --muted-foreground: var(--text-muted);
  --accent: var(--brand-highlight);
  --accent-foreground: var(--text-primary);
  --destructive: var(--brand-danger);
  --destructive-foreground: var(--text-primary);
  --border: var(--border-subtle);
  --input: var(--border-subtle);
  --ring: var(--brand-accent);
  --sidebar: var(--brand-surface);
  --sidebar-foreground: var(--text-primary);
  --sidebar-primary: var(--brand-accent);
  --sidebar-primary-foreground: var(--brand-deep);
  --sidebar-accent: var(--brand-elevated);
  --sidebar-accent-foreground: var(--text-primary);
  --sidebar-border: var(--border-subtle);
  --sidebar-ring: var(--brand-accent);
}

@layer base {
  * {
    @apply border-border outline-ring/50;
  }
  body {
    @apply bg-background text-foreground antialiased;
  }
  html {
    scroll-behavior: smooth;
  }
}

/* ============================================
   UTILITY CLASSES - Design System
   ============================================ */

@layer utils {
  /* Glass Morphism */
  .glass {
    background: var(--glass-bg);
    backdrop-filter: blur(20px);
    -webkit-backdrop-filter: blur(20px);
    border: 1px solid var(--glass-border);
  }

  .glass-elevated {
    background: var(--glass-bg-elevated);
    backdrop-filter: blur(24px);
    -webkit-backdrop-filter: blur(24px);
    border: 1px solid var(--border-glass);
  }

  .glass-card {
    background: var(--glass-bg);
    backdrop-filter: blur(20px);
    -webkit-backdrop-filter: blur(20px);
    border: 1px solid var(--glass-border);
    border-radius: 1.5rem;
  }

  /* Grain Texture */
  .grain {
    position: relative;
  }
  .grain::before {
    content: "";
    position: absolute;
    inset: 0;
    background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 200 200' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='noise'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.65' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23noise)'/%3E%3C/svg%3E");
    opacity: 0.03;
    pointer-events: none;
    z-index: 1;
  }

  /* Mesh Gradients */
  .mesh-gradient {
    background: radial-gradient(
        ellipse at 20% 20%,
        var(--glow-accent) 0%,
        transparent 50%
      ),
      radial-gradient(
        ellipse at 80% 80%,
        var(--glow-highlight) 0%,
        transparent 50%
      ),
      var(--brand-deep);
  }

  .mesh-gradient-subtle {
    background: radial-gradient(
        ellipse at 10% 10%,
        rgba(52, 211, 153, 0.08) 0%,
        transparent 40%
      ),
      radial-gradient(
        ellipse at 90% 90%,
        rgba(99, 102, 241, 0.08) 0%,
        transparent 40%
      ),
      var(--brand-deep);
  }

  .mesh-gradient-hero {
    background: radial-gradient(
        ellipse at 30% 0%,
        rgba(52, 211, 153, 0.2) 0%,
        transparent 50%
      ),
      radial-gradient(
        ellipse at 70% 100%,
        rgba(99, 102, 241, 0.2) 0%,
        transparent 50%
      ),
      radial-gradient(ellipse at 50% 50%, rgba(99, 102, 241, 0.05) 0%, transparent 70%),
      var(--brand-deep);
  }

  /* Hyper Border (Gradient animated border) */
  .hyper-border {
    position: relative;
    background: var(--brand-surface);
    border-radius: 1.5rem;
  }
  .hyper-border::before {
    content: "";
    position: absolute;
    inset: -1px;
    border-radius: inherit;
    padding: 1px;
    background: linear-gradient(
      135deg,
      var(--brand-accent),
      var(--brand-highlight),
      var(--brand-accent)
    );
    background-size: 200% 200%;
    -webkit-mask:
      linear-gradient(#fff 0 0) content-box,
      linear-gradient(#fff 0 0);
    -webkit-mask-composite: xor;
    mask-composite: exclude;
    animation: border-gradient 3s ease infinite;
    pointer-events: none;
  }

  /* Glow Effects */
  .glow-accent {
    box-shadow:
      0 0 20px var(--glow-accent),
      0 0 40px var(--glow-accent);
  }

  .glow-highlight {
    box-shadow:
      0 0 20px var(--glow-highlight),
      0 0 40px var(--glow-highlight);
  }

  .hover-glow-accent {
    transition: box-shadow 0.3s ease;
  }
  .hover-glow-accent:hover {
    box-shadow:
      0 0 20px var(--glow-accent),
      0 0 40px var(--glow-accent);
  }

  .hover-glow-highlight {
    transition: box-shadow 0.3s ease;
  }
  .hover-glow-highlight:hover {
    box-shadow:
      0 0 20px var(--glow-highlight),
      0 0 40px var(--glow-highlight);
  }

  /* Text Gradients */
  .text-gradient {
    @apply bg-clip-text text-transparent;
  }

  .text-gradient-accent {
    background: linear-gradient(135deg, var(--brand-accent), #6ee7b7);
    -webkit-background-clip: text;
    background-clip: text;
    color: transparent;
  }

  .text-gradient-highlight {
    background: linear-gradient(135deg, var(--brand-highlight), #a5b4fc);
    -webkit-background-clip: text;
    background-clip: text;
    color: transparent;
  }

  .text-gradient-brand {
    background: linear-gradient(
      135deg,
      var(--brand-accent),
      var(--brand-highlight)
    );
    -webkit-background-clip: text;
    background-clip: text;
    color: transparent;
  }

  /* Card Hover Effects */
  .card-hover {
    transition:
      transform 0.3s ease,
      box-shadow 0.3s ease;
  }
  .card-hover:hover {
    transform: translateY(-4px);
    box-shadow:
      0 20px 40px rgba(0, 0, 0, 0.3),
      0 0 40px var(--glow-accent);
  }

  /* Shimmer Effect */
  .shimmer {
    background: linear-gradient(
      90deg,
      transparent 0%,
      rgba(255, 255, 255, 0.05) 50%,
      transparent 100%
    );
    background-size: 200% 100%;
    animation: shimmer 2s linear infinite;
  }

  /* Grid Background */
  .bg-grid {
    --bg-grid-color: rgba(255, 255, 255, 0.03);
    background-color: transparent;
    background-image: linear-gradient(
        90deg,
        var(--bg-grid-color) 1px,
        transparent 1px
      ),
      linear-gradient(180deg, var(--bg-grid-color) 1px, transparent 1px);
    background-size: 64px 64px;
  }

  .bg-grid-small {
    --bg-grid-color: rgba(255, 255, 255, 0.02);
    background-color: transparent;
    background-image: linear-gradient(
        90deg,
        var(--bg-grid-color) 1px,
        transparent 1px
      ),
      linear-gradient(180deg, var(--bg-grid-color) 1px, transparent 1px);
    background-size: 24px 24px;
  }

  /* Dot Pattern */
  .dot-pattern {
    --dot-color: rgba(255, 255, 255, 0.1);
    --dot-background: transparent;
    opacity: 0.8;
    background-image: radial-gradient(
      var(--dot-color) 0.5px,
      var(--dot-background) 0.5px
    );
    background-size: var(--size, 10px) var(--size, 10px);
  }

  /* Scanline Effect */
  .scanline {
    position: relative;
    overflow: hidden;
  }
  .scanline::after {
    content: "";
    position: absolute;
    inset: 0;
    background: linear-gradient(
      90deg,
      transparent,
      rgba(52, 211, 153, 0.1),
      transparent
    );
    animation: scanline 3s ease-in-out infinite;
    pointer-events: none;
  }

  /* Focus ring for dark theme */
  .focus-ring {
    @apply focus-visible:ring-2 focus-visible:ring-primary focus-visible:ring-offset-2 focus-visible:ring-offset-background outline-none;
  }
}

/* ============================================
   COMPONENT STYLES
   ============================================ */

/* Citation */
.citation {
  position: relative;
  display: inline-block;
  padding: 4px;
  border-radius: 0.5rem;
  color: var(--foreground);
  font-style: italic;
  --gap: -16px;
}

.citation::before {
  content: "\201C";
  font-size: 3rem;
  position: absolute;
  top: -12px;
  left: -12px;
  line-height: 1;
  color: var(--brand-accent);
}

.citation::after {
  content: "\201D";
  font-size: 3rem;
  position: absolute;
  bottom: -16px;
  right: -4px;
  line-height: 1;
  color: var(--brand-accent);
}

.citation strong {
  font-weight: 700;
  background: rgba(52, 211, 153, 0.2);
  display: inline;
  padding: 2px;
  margin: -2px;
}

/* Prose (Typography) */
.prose {
  scroll-margin-top: 40px;

  & h1,
  & h2,
  & h3,
  & h4,
  & h5,
  & h6 {
    position: relative;
    scroll-margin-top: 70px;

    &:hover {
      & .icon-link {
        opacity: 1;
      }
    }
  }

  & .icon.icon-link {
    width: 20px;
    height: 100%;
    display: block;
    position: absolute;
    display: flex;
    align-items: center;
    justify-content: center;
    left: -24px;
    opacity: 0;
    transition: opacity 0.2s ease;

    &::before {
      content: "#";
      font-size: 1.5rem;
      color: var(--brand-accent);
    }
  }
}

/* Scrollbar styling for dark theme */
::-webkit-scrollbar {
  width: 8px;
  height: 8px;
}

::-webkit-scrollbar-track {
  background: var(--brand-deep);
}

::-webkit-scrollbar-thumb {
  background: var(--brand-elevated);
  border-radius: 4px;
}

::-webkit-scrollbar-thumb:hover {
  background: var(--text-muted);
}

/* Selection */
::selection {
  background: rgba(52, 211, 153, 0.3);
  color: var(--text-primary);
}

