/* Context-based theming for B2C and B2B interfaces - Dark First */

/* B2C Theme - Emotional, warm, consumer-friendly */
.theme-b2c {
  /* Color variants for B2C - Dark theme adapted */
  --accent-primary: var(--brand-accent);
  --accent-secondary: var(--brand-highlight);
  --surface-elevated: var(--brand-elevated);
  --surface-card: var(--brand-surface);

  /* Status colors with glow */
  --status-success: #34d399;
  --status-warning: #fbbf24;
  --status-danger: #f43f5e;
  --status-info: #6366f1;

  /* B2C specific spacing and layout - More spacious */
  --spacing-card: 1.5rem;
  --spacing-section: 3rem;
  --radius-card: 1.5rem;
  --shadow-card: 0 4px 24px rgba(0, 0, 0, 0.4),
    0 0 40px rgba(52, 211, 153, 0.05);
}

/* B2B Theme - Professional, compact, data-dense */
.theme-b2b {
  /* Color variants for B2B - Dark theme adapted */
  --accent-primary: var(--brand-highlight);
  --accent-secondary: var(--brand-accent);
  --surface-elevated: var(--brand-elevated);
  --surface-card: var(--brand-surface);

  /* Status colors - More muted */
  --status-success: #22c55e;
  --status-warning: #eab308;
  --status-danger: #ef4444;
  --status-info: #3b82f6;

  /* B2B specific spacing and layout - More compact */
  --spacing-card: 1rem;
  --spacing-section: 2rem;
  --radius-card: 0.75rem;
  --shadow-card: 0 2px 12px rgba(0, 0, 0, 0.3);
