import * as React from "react";
import { cn } from "@/lib/utils";

const DPE_GRADES = [
  { grade: "A", color: "#059669", bgColor: "bg-emerald-600", label: "A" },
  { grade: "B", color: "#10b981", bgColor: "bg-emerald-500", label: "B" },
  { grade: "C", color: "#84cc16", bgColor: "bg-lime-500", label: "C" },
  { grade: "D", color: "#eab308", bgColor: "bg-yellow-500", label: "D" },
  { grade: "E", color: "#f97316", bgColor: "bg-orange-500", label: "E" },
  { grade: "F", color: "#ef4444", bgColor: "bg-red-500", label: "F" },
  { grade: "G", color: "#dc2626", bgColor: "bg-red-600", label: "G" },
] as const;

type DPEGrade = (typeof DPE_GRADES)[number]["grade"];

type DPEScaleProps = {
  grade?: DPEGrade | string | null;
  showLabel?: boolean;
  size?: "sm" | "md" | "lg";
  className?: string;
};

function DPEScale({
  grade,
  showLabel = true,
  size = "md",
  className,
}: DPEScaleProps) {
  const normalizedGrade = grade?.toUpperCase() as DPEGrade;
  const activeIndex = DPE_GRADES.findIndex((g) => g.grade === normalizedGrade);

  const sizeClasses = {
    sm: "h-4 text-xs",
    md: "h-6 text-sm",
    lg: "h-8 text-base",
  };

  const widthClasses = {
    sm: ["w-6", "w-7", "w-8", "w-9", "w-10", "w-11", "w-12"],
    md: ["w-8", "w-10", "w-12", "w-14", "w-16", "w-18", "w-20"],
    lg: ["w-10", "w-12", "w-14", "w-16", "w-18", "w-20", "w-22"],
  };

  return (
    <div className={cn("flex flex-col gap-0.5", className)}>
      {DPE_GRADES.map((dpe, index) => {
        const isActive = index === activeIndex;
        return (
          <div
            key={dpe.grade}
            className={cn(
              "flex items-center transition-all duration-300",
              sizeClasses[size],
              widthClasses[size][index],
              isActive ? "scale-105" : "opacity-60",
            )}
          >
            <div
              className={cn(
                "flex h-full w-full items-center justify-between rounded-r-md px-2 font-semibold text-white",
                isActive && "shadow-lg",
              )}
              style={{
                backgroundColor: dpe.color,
                boxShadow: isActive ? `0 0 20px ${dpe.color}50` : undefined,
              }}
            >
              <span>{dpe.label}</span>
              {isActive && showLabel && (
                <span className="ml-2 text-white/90">
                  {normalizedGrade}
                </span>
              )}
            </div>
          </div>
        );
      })}
    </div>
  );
}

type DPEBadgeProps = {
  grade?: DPEGrade | string | null;
  size?: "sm" | "md" | "lg";
  className?: string;
};

function DPEBadge({ grade, size = "md", className }: DPEBadgeProps) {
  const normalizedGrade = grade?.toUpperCase() as DPEGrade;
  const dpe = DPE_GRADES.find((g) => g.grade === normalizedGrade);

  if (!dpe) {
    return (
      <div
        className={cn(
          "inline-flex items-center justify-center rounded-lg bg-muted text-muted-foreground font-semibold",
          size === "sm" && "h-6 w-6 text-xs",
          size === "md" && "h-8 w-8 text-sm",
          size === "lg" && "h-10 w-10 text-base",
          className,
        )}
      >
        ?
      </div>
    );
  }

  return (
    <div
      className={cn(
        "inline-flex items-center justify-center rounded-lg font-bold text-white transition-all duration-200",
        size === "sm" && "h-6 w-6 text-xs",
        size === "md" && "h-8 w-8 text-sm",
        size === "lg" && "h-10 w-10 text-base",
        className,
      )}
      style={{
        backgroundColor: dpe.color,
        boxShadow: `0 0 15px ${dpe.color}40`,
      }}
    >
      {dpe.grade}
    </div>
  );
}

export { DPEScale, DPEBadge, DPE_GRADES, type DPEGrade };

import * as React from "react";
import { cn } from "@/lib/utils";
import { TrendingUp, TrendingDown, Minus } from "lucide-react";

type StatsCardProps = {
  label: string;
  value: string | number;
  trend?: {
    value: number;
    label?: string;
  };
  icon?: React.ReactNode;
  variant?: "default" | "accent" | "highlight";
  className?: string;
};

function StatsCard({
  label,
  value,
  trend,
  icon,
  variant = "default",
  className,
}: StatsCardProps) {
  const trendDirection =
    trend?.value === 0 ? "neutral" : trend?.value && trend.value > 0 ? "up" : "down";

  const variantStyles = {
    default: "glass-card",
    accent:
      "glass-card border-[var(--brand-accent)]/20 shadow-[0_0_30px_var(--glow-accent)]",
    highlight:
      "glass-card border-[var(--brand-highlight)]/20 shadow-[0_0_30px_var(--glow-highlight)]",
  };

  return (
    <div
      className={cn(
        "relative overflow-hidden p-6 transition-all duration-300 hover:scale-[1.02]",
        variantStyles[variant],
        className,
      )}
    >
      <div className="flex items-start justify-between">
        <div className="flex-1 space-y-3">
          <p className="text-sm font-medium text-muted-foreground">{label}</p>
          <p className="text-3xl font-bold tracking-tight text-foreground">
            {value}
          </p>
          {trend && (
            <div className="flex items-center gap-1.5">
              {trendDirection === "up" && (
                <TrendingUp className="size-4 text-success" />
              )}
              {trendDirection === "down" && (
                <TrendingDown className="size-4 text-destructive" />
              )}
              {trendDirection === "neutral" && (
                <Minus className="size-4 text-muted-foreground" />
              )}
              <span
                className={cn(
                  "text-sm font-medium",
                  trendDirection === "up" && "text-success",
                  trendDirection === "down" && "text-destructive",
                  trendDirection === "neutral" && "text-muted-foreground",
                )}
              >
                {trend.value > 0 ? "+" : ""}
                {trend.value}%
              </span>
              {trend.label && (
                <span className="text-sm text-muted-foreground">
                  {trend.label}
                </span>
              )}
            </div>
          )}
        </div>
        {icon && (
          <div
            className={cn(
              "flex size-12 items-center justify-center rounded-xl",
              variant === "accent" &&
                "bg-[var(--brand-accent)]/10 text-[var(--brand-accent)]",
              variant === "highlight" &&
                "bg-[var(--brand-highlight)]/10 text-[var(--brand-highlight)]",
              variant === "default" && "bg-muted text-muted-foreground",
            )}
          >
            {icon}
          </div>
        )}
      </div>
    </div>
  );
}

type MiniStatsProps = {
  label: string;
  value: string | number;
  icon?: React.ReactNode;
  className?: string;
};

function MiniStats({ label, value, icon, className }: MiniStatsProps) {
  return (
    <div
      className={cn(
        "flex items-center gap-3 rounded-xl bg-white/5 px-4 py-3",
        className,
      )}
    >
      {icon && (
        <div className="flex size-8 items-center justify-center rounded-lg bg-primary/10 text-primary">
          {icon}
        </div>
      )}
      <div className="flex-1">
        <p className="text-xs text-muted-foreground">{label}</p>
        <p className="font-semibold text-foreground">{value}</p>
      </div>
    </div>
  );
}

export { StatsCard, MiniStats };

