  label?: string;
  showValue?: boolean;
  size?: "sm" | "md" | "lg";
  variant?: "accent" | "highlight" | "gradient";
  className?: string;
};

function GradientProgress({
  value,
  max = 100,
  label,
  showValue = true,
  size = "md",
  variant = "gradient",
  className,
}: GradientProgressProps) {
  const percentage = Math.min(100, Math.max(0, (value / max) * 100));

  const sizeStyles = {
    sm: "h-1.5",
    md: "h-2.5",
    lg: "h-4",
