"use client";

import * as ProgressPrimitive from "@radix-ui/react-progress";
import * as React from "react";

import { cn } from "@/lib/utils";

type ProgressProps = React.ComponentProps<typeof ProgressPrimitive.Root> & {
  variant?: "default" | "accent" | "highlight" | "gradient";
};

function Progress({
  className,
  value,
  variant = "default",
  ...props
}: ProgressProps) {
  const variantStyles = {
    default: "bg-primary",
    accent: "bg-[var(--brand-accent)] shadow-[0_0_15px_var(--glow-accent)]",
    highlight: "bg-[var(--brand-highlight)] shadow-[0_0_15px_var(--glow-highlight)]",
    gradient: "bg-gradient-to-r from-[var(--brand-accent)] to-[var(--brand-highlight)] shadow-[0_0_15px_var(--glow-accent)]",
  };

  return (
    <ProgressPrimitive.Root
      data-slot="progress"
      className={cn(
        "relative h-2.5 w-full overflow-hidden rounded-full bg-white/5",
        className,
      )}
      {...props}
    >
      <ProgressPrimitive.Indicator
        data-slot="progress-indicator"
        className={cn(
          "size-full flex-1 rounded-full transition-all duration-500 ease-out",
          variantStyles[variant],
        )}
        style={{ transform: `translateX(-${100 - (value ?? 0)}%)` }}
      />
    </ProgressPrimitive.Root>
  );
}

export { Progress };

import { cn } from "@/lib/utils";

function Skeleton({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="skeleton"
      className={cn(
        "rounded-lg bg-white/5 shimmer",
        className,
      )}
      {...props}
    />
  );
}

export { Skeleton };

