        <div className="flex items-center gap-2">
          <LogoSvg
            size={28}
            onClick={() => {
              router.push("/");
            }}
            className="cursor-pointer"
          />
          <motion.p
            style={{
              scale: useTransform(
                scrollYBoundedProgressDelayed,
                [0, 1],
                [1, 0.9],
              ),
            }}
            className="flex origin-left items-center text-lg font-semibold text-foreground max-sm:hidden"
          >
            {SiteConfig.title}
          </motion.p>
        </div>
        <motion.nav
          style={{
            opacity: useTransform(
              scrollYBoundedProgressDelayed,
              [0, 1],
              [1, 0],
            ),
          }}
          className="flex items-center gap-6 text-sm font-medium"
