"use client";

import { animate } from "motion/react";
import { useEffect, useRef } from "react";
import { SectionLayout } from "./section-layout";

type StatProps = {
  number: number;
  suffix: string;
  text: string;
};

const stats: StatProps[] = [
  {
    number: 50,
    suffix: "K+",
    text: "Annonces analysées chaque mois",
  },
  {
    number: 2.5,
    suffix: "K",
    text: "Utilisateurs actifs",
  },
  {
    number: 98,
    suffix: "%",
    text: "Taux de satisfaction",
  },
  {
    number: 12,
    suffix: "%",
    text: "Économie moyenne sur le prix d'achat",
  },
];

export function StatsSection() {
  return (
    <SectionLayout size="lg">
      <div className="glass-card grid w-full items-center gap-8 p-8 sm:grid-cols-2 md:grid-cols-4 md:gap-0 lg:p-12">
        {stats.map((stat, index) => (
          <div
            key={index}
            className="relative text-center md:px-6"
          >
            {index > 0 && (
              <div className="absolute left-0 top-1/2 hidden h-12 w-px -translate-y-1/2 bg-[var(--border-subtle)] md:block" />
            )}
            <h4 className="text-gradient-brand mb-2 text-4xl font-bold tabular-nums md:text-5xl">
              <Counter from={0} to={stat.number} />
              {stat.suffix}
            </h4>
            <p className="text-muted-foreground text-sm">{stat.text}</p>
          </div>
        ))}
      </div>
    </SectionLayout>
  );
}

function Counter({
  from,
  to,
  duration = 2,
}: {
  from: number;
  to: number;
  duration?: number;
}) {
  const nodeRef = useRef<HTMLSpanElement>(null);

  useEffect(() => {
    if (!nodeRef.current) return;
    const node = nodeRef.current;

    const controls = animate(from, to, {
      duration,
      ease: "easeInOut",

      onUpdate(value) {
        if (to >= 100) {
          node.textContent = Math.round(value).toString();
        } else {
          node.textContent = value.toFixed(1);
        }
      },
    });

    return () => controls.stop();
  }, [from, to, duration]);

  return <span ref={nodeRef}>{from}</span>;
}

