import { BentoGridSection } from "@/features/landing/bento-section";
import { FAQSection } from "@/features/landing/faq-section";
import { Hero } from "@/features/landing/hero";
import { LandingHeader } from "@/features/landing/landing-header";
import { StatsSection } from "@/features/landing/stats-section";
import { Footer } from "@/features/layout/footer";
import { Pricing } from "@/features/plans/pricing-section";

export default function HomePage() {
  return (
    <div className="relative flex h-fit flex-col">
      <div className="mt-16" />

      <LandingHeader />

      <Hero />

      <StatsSection />

      <BentoGridSection />

      <div id="pricing">
        <Pricing />
      </div>

      <FAQSection
        faq={[
          {
            question: "Qu'est-ce que ChooseWisely ?",
            answer:
              "ChooseWisely est une plateforme innovante qui agrège toutes les annonces immobilières françaises et les enrichit avec les données DVF (prix de vente réels) et DPE pour vous aider à prendre les meilleures décisions d'investissement.",
          },
          {
            question: "Comment fonctionne l'analyse DVF ?",
            answer:
              "Notre système analyse automatiquement les ventes immobilières passées dans le quartier de chaque bien pour vous donner une estimation précise de sa valeur réelle et de sa marge de négociation potentielle.",
          },
          {
            question: "Les données sont-elles fiables ?",
            answer:
              "Oui, nous utilisons uniquement des données officielles : les ventes DVF proviennent des notaires et sont publiées par data.gouv.fr, les données DPE proviennent de l'ADEME.",
          },
          {
            question: "Puis-je créer des alertes ?",
            answer:
              "Absolument ! Vous pouvez sauvegarder vos recherches et recevoir des alertes par email dès qu'un nouveau bien correspondant à vos critères est publié.",
          },
          {
            question: "Quelles sont les limites du plan gratuit ?",
            answer:
              "Le plan gratuit vous permet de rechercher des biens et de consulter les analyses de base. Les fonctionnalités avancées comme les alertes illimitées, l'export des données et l'accès API sont réservées aux plans payants.",
          },
          {
            question: "Comment fonctionne l'aide à la négociation ?",
            answer:
              "Notre algorithme analyse les ventes DVF récentes, le temps moyen de vente dans le quartier et les caractéristiques du bien pour vous suggérer un prix de négociation réaliste et les arguments à utiliser.",
          },
        ]}
      />

      <Footer />
    </div>
  );
}

