"use client";

import { logger } from "@/lib/logger";
import { useState } from "react";
import { Card, CardContent, CardHeader } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Textarea } from "@/components/ui/textarea";
import {
  Trash2,
  Edit3,
  MapPin,
  Euro,
  Home,
  Save,
  X,
  ExternalLink,
  Star,
} from "lucide-react";
import { DPECard } from "@/components/energy/dpe-card";
import { useDPE } from "@/hooks/use-dpe";
import { deleteFavoriteAction, updateFavoriteAction } from "./favorites.action";
import { cn } from "@/lib/utils";
import type { Favorite, Property } from "@/generated/prisma";

type FavoriteWithProperty = Favorite & {
  property: Property;
};

type FavoriteCardProps = {
  favorite: FavoriteWithProperty;
  onUpdate: () => void;
};

export function FavoriteCard({ favorite, onUpdate }: FavoriteCardProps) {
  const [isLoading, setIsLoading] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [notes, setNotes] = useState(favorite.notes ?? "");
  const [priority, setPriority] = useState<"high" | "medium" | "low">(
    favorite.priority as "high" | "medium" | "low",
  );

  const { isLoading: dpeLoading, enrichFavorite, formatDPEData } = useDPE();
  const [dpeExpanded, setDpeExpanded] = useState(false);

  const dpeData = formatDPEData(favorite);

  const handleRefreshDPE = async () => {
    try {
      await enrichFavorite(favorite.id);
      onUpdate(); // Refresh the favorite data
    } catch (error) {
      logger.debug("Failed to refresh DPE data:", error);
    }
  };

  const handleDelete = async () => {
    if (
      !confirm(
        `Êtes-vous sûr de vouloir supprimer "${favorite.property.title}" de vos favoris ?`,
      )
    ) {
      return;
    }

    setIsLoading(true);
    try {
      await deleteFavoriteAction(favorite.id);
      onUpdate();
    } catch (error) {
      logger.debug("Erreur lors de la suppression:", error);
    } finally {
      setIsLoading(false);
    }
  };

  const handleSave = async () => {
    setIsLoading(true);
    try {
      await updateFavoriteAction({
        id: favorite.id,
        notes: notes,
        priority: priority,
      });
      setIsEditing(false);
      onUpdate();
    } catch (error) {
      logger.debug("Erreur lors de la sauvegarde:", error);
    } finally {
      setIsLoading(false);
    }
  };

  const handleCancel = () => {
    setIsEditing(false);
    setNotes(favorite.notes ?? "");
    setPriority(favorite.priority as "high" | "medium" | "low");
  };

  const handleStatusChange = async (newStatus: string) => {
    setIsLoading(true);
    try {
      await updateFavoriteAction({
        id: favorite.id,
        status: newStatus as "saved" | "visited" | "contacted" | "rejected",
      });
      onUpdate();
    } catch (error) {
      logger.debug("Erreur lors de la mise à jour:", error);
    } finally {
      setIsLoading(false);
    }
  };

  const getPriorityColor = (priority: string) => {
    switch (priority) {
      case "high":
        return "destructive";
      case "low":
        return "secondary";
      default:
        return "default";
    }
  };

  const getStatusLabel = (status: string) => {
    switch (status) {
      case "saved":
        return "Sauvegardé";
      case "visited":
        return "Visité";
      case "contacted":
        return "Contacté";
      case "rejected":
        return "Rejeté";
      default:
        return status;
    }
  };

  return (
    <Card className="transition-shadow hover:shadow-md">
      <CardHeader className="pb-3">
        <div className="flex items-start justify-between">
          <div className="min-w-0 flex-1 space-y-2">
            <div className="flex items-center gap-2">
              <h3 className="truncate font-semibold">
                {favorite.property.title}
              </h3>
              <div className="flex flex-shrink-0 items-center gap-1">
                <Badge
                  variant={getPriorityColor(favorite.priority)}
                  className="text-xs"
                >
                  {favorite.priority === "high" && (
                    <Star className="mr-1 h-3 w-3" />
                  )}
                  {favorite.priority === "high"
                    ? "Priorité élevée"
                    : favorite.priority === "low"
                      ? "Priorité faible"
                      : "Priorité normale"}
                </Badge>
              </div>
            </div>

            <div className="space-y-1">
              <div className="text-muted-foreground flex items-center gap-2 text-sm">
                <MapPin className="h-3 w-3" />
                {favorite.property.address}, {favorite.property.city} (
                {favorite.property.postalCode})
              </div>

              <div className="flex items-center gap-4 text-sm">
                <div className="flex items-center gap-1">
                  <Euro className="h-3 w-3" />
                  {favorite.property.price.toLocaleString("fr-FR")}€
                </div>
                {favorite.property.surface && (
                  <div className="flex items-center gap-1">
                    <Home className="h-3 w-3" />
                    {favorite.property.surface}m²
                  </div>
                )}
                {favorite.property.rooms && (
                  <div>{favorite.property.rooms} pièces</div>
                )}
              </div>
            </div>

            {/* Status badges */}
            <div className="flex flex-wrap items-center gap-2">
              {["saved", "visited", "contacted", "rejected"].map((status) => (
                <button
                  key={status}
                  onClick={async () => handleStatusChange(status)}
                  disabled={isLoading}
                  className={cn(
                    "focus:ring-ring inline-flex cursor-pointer items-center rounded-full border px-2.5 py-0.5 text-xs font-semibold transition-colors hover:opacity-80 focus:ring-2 focus:ring-offset-2 focus:outline-none",
                    favorite.status === status
                      ? "border-primary bg-primary text-primary-foreground"
                      : "border-input bg-background hover:bg-accent hover:text-accent-foreground",
                  )}
                >
                  {getStatusLabel(status)}
                </button>
              ))}
            </div>
          </div>
        </div>
      </CardHeader>

      <CardContent className="space-y-4">
        {/* DPE Section */}
        <div className="space-y-3">
          <div className="flex items-center justify-between">
            <h4 className="text-sm font-medium">Performance Énergétique</h4>
            <Button
              variant="ghost"
              size="sm"
              onClick={() => setDpeExpanded(!dpeExpanded)}
              className="h-8 text-xs"
            >
              {dpeExpanded ? "Masquer" : "Voir"} les détails
            </Button>
          </div>

          {dpeExpanded && (
            <DPECard
              data={dpeData}
              isLoading={dpeLoading}
              onRefresh={handleRefreshDPE}
              compact
            />
          )}

          {!dpeExpanded && dpeData.dpeClass && (
            <div className="flex items-center gap-3 p-3 bg-muted rounded-lg">
              <div className="flex items-center gap-2">
                <span className="text-xs text-muted-foreground">DPE</span>
                <div className={`w-8 h-8 rounded-full flex items-center justify-center text-xs font-bold ${
                  dpeData.dpeClass === "A" || dpeData.dpeClass === "B" ? "bg-green-500 text-white" :
                  dpeData.dpeClass === "C" || dpeData.dpeClass === "D" ? "bg-yellow-400 text-black" :
                  "bg-red-500 text-white"
                }`}>
                  {dpeData.dpeClass}
                </div>
              </div>

              {dpeData.rentalRestrictionRisk && (
                <div className="flex items-center gap-2">
                  <span className="text-xs text-muted-foreground">Risque location</span>
                  <Badge variant={
                    dpeData.rentalRestrictionRisk === "critical" ? "destructive" :
                    dpeData.rentalRestrictionRisk === "high" ? "destructive" :
                    dpeData.rentalRestrictionRisk === "medium" ? "default" : "secondary"
                  } className="text-xs">
                    {dpeData.rentalRestrictionRisk === "critical" ? "Critique" :
                     dpeData.rentalRestrictionRisk === "high" ? "Élevé" :
                     dpeData.rentalRestrictionRisk === "medium" ? "Moyen" : "Faible"}
                  </Badge>
                </div>
              )}

              {dpeData.annualEnergyCost && (
                <div className="flex items-center gap-2">
                  <span className="text-xs text-muted-foreground">Coût/mois</span>
                  <span className="text-sm font-semibold">
                    {Math.round(dpeData.annualEnergyCost / 12)}€
                  </span>
                </div>
              )}
            </div>
          )}
        </div>

        {/* Notes section */}
        <div className="space-y-2">
          <h4 className="text-sm font-medium">Notes personnelles :</h4>
          {isEditing ? (
            <div className="space-y-2">
              <Textarea
                value={notes}
                onChange={(e) => setNotes(e.target.value)}
                placeholder="Ajoutez vos notes sur ce bien..."
                className="min-h-[80px]"
                maxLength={500}
              />
              <div className="flex items-center justify-between">
                <p className="text-muted-foreground text-xs">
                  {notes.length}/500 caractères
                </p>
                <div className="flex items-center gap-2">
                  <Button
                    onClick={handleCancel}
                    variant="outline"
                    size="sm"
                    disabled={isLoading}
                  >
                    <X className="mr-1 h-3 w-3" />
                    Annuler
                  </Button>
                  <Button onClick={handleSave} size="sm" disabled={isLoading}>
                    <Save className="mr-1 h-3 w-3" />
                    Sauvegarder
                  </Button>
                </div>
              </div>
            </div>
          ) : (
            <div className="space-y-2">
              {favorite.notes ? (
                <p className="bg-muted rounded-md p-3 text-sm whitespace-pre-wrap">
                  {favorite.notes}
                </p>
              ) : (
                <p className="text-muted-foreground text-sm italic">
                  Aucune note pour ce bien
                </p>
              )}
            </div>
          )}
        </div>

        {/* Actions */}
        <div className="flex items-center justify-between gap-2">
          <div className="text-muted-foreground text-xs">
            Ajouté le {new Date(favorite.createdAt).toLocaleDateString("fr-FR")}
          </div>

          <div className="flex items-center gap-1">
            {favorite.property.sourceUrl && (
              <Button asChild variant="ghost" size="sm" title="Voir l'annonce">
                <a
                  href={favorite.property.sourceUrl}
                  target="_blank"
                  rel="noopener noreferrer"
                >
                  <ExternalLink className="h-4 w-4" />
                </a>
              </Button>
            )}

            <Button
              onClick={() => setIsEditing(!isEditing)}
              variant="ghost"
              size="sm"
              disabled={isLoading}
              title="Modifier les notes"
            >
              <Edit3 className="h-4 w-4" />
            </Button>

            <Button
              onClick={handleDelete}
              variant="ghost"
              size="sm"
              disabled={isLoading}
              title="Supprimer des favoris"
              className="text-destructive hover:text-destructive"
            >
              <Trash2 className="h-4 w-4" />
            </Button>
          </div>
        </div>
      </CardContent>
    </Card>
  );
}

