"use client";

import { logger } from "@/lib/logger";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { SafeImage } from "@/components/ui/safe-image";
import type { Property } from "@/lib/moteurimmo/types";
import { useState } from "react";
import { usePathname } from "next/navigation";
import { toggleFavoriteAction } from "@/features/favorites/favorites.action";
import { ComparisonButton } from "@/features/comparison/comparison-button";
import { FinanceButton } from "@/features/finance/finance-button";
import {
  Bed,
  Calendar,
  Heart,
  Home,
  MapPin,
  Ruler,
  ExternalLink,
  ArrowRight,
} from "lucide-react";
import Link from "next/link";
import { cn } from "@/lib/utils";

type PropertyCardProps = {
  property: Property;
  view?: "list" | "grid";
  onFavorite?: (property: Property) => void;
  isFavorite?: boolean;
};

export function PropertyCard({
  property,
  view = "list",
  onFavorite,
  isFavorite = false,
}: PropertyCardProps) {
  const pathname = usePathname();
  const isInOrgContext = pathname.startsWith("/orgs/");
  const detailUrl = isInOrgContext
    ? `${pathname}/${property.id}`
    : `/properties/${property.id}`;
  const [isFavorited, setIsFavorited] = useState(isFavorite);
  const [isLoading, setIsLoading] = useState(false);

  const handleFavoriteClick = async () => {
    if (isLoading) return;

    setIsLoading(true);
    try {
      const result = await toggleFavoriteAction(property.uniqueId);
      setIsFavorited(result.isFavorite);
      onFavorite?.(property);
    } catch (error) {
      logger.debug("Erreur lors de la mise à jour du favori:", error);
    } finally {
      setIsLoading(false);
    }
  };

  const formatPrice = (price: number) => {
    return new Intl.NumberFormat("fr-FR", {
      style: "currency",
      currency: "EUR",
      maximumFractionDigits: 0,
    }).format(price);
  };

  const formatDate = (dateString: string) => {
    return new Intl.DateTimeFormat("fr-FR", {
      day: "numeric",
      month: "short",
    }).format(new Date(dateString));
  };

  const getTypeLabel = (type: string) => {
    return type === "sale" ? "Vente" : "Location";
  };

  const getCategoryLabel = (category: string) => {
    const labels = {
      flat: "Appartement",
      house: "Maison",
      land: "Terrain",
      office: "Bureau",
      shop: "Commerce",
      warehouse: "Entrepôt",
      building: "Immeuble",
      "parking/garage/box": "Parking",
    };
    return labels[category as keyof typeof labels] || category;
  };

  const pricePerSqm = property.surface
    ? Math.round(property.price / property.surface)
    : null;

  if (view === "grid") {
    return (
      <div className="glass-card group overflow-hidden transition-all duration-300 hover:scale-[1.02] hover:shadow-[0_20px_40px_rgba(0,0,0,0.3),0_0_40px_var(--glow-accent)]">
        <div className="relative aspect-[4/3] overflow-hidden">
          <SafeImage
            src={property.mainImage ?? property.images[0]}
            alt={property.title}
            fill
            className="object-cover transition-transform duration-500 group-hover:scale-110"
          />
          <div className="absolute inset-0 bg-gradient-to-t from-black/60 via-transparent to-transparent" />
          <div className="absolute top-3 left-3 flex gap-2">
            <Badge variant="glass">{getTypeLabel(property.type)}</Badge>
            <Badge variant="outline" className="border-white/20 bg-black/30 text-white">
              {getCategoryLabel(property.category)}
            </Badge>
          </div>
          <Button
            variant="ghost"
            size="icon"
            className={cn(
              "absolute top-3 right-3 rounded-xl bg-black/30 backdrop-blur-sm transition-all duration-200",
              isFavorited
                ? "text-red-500 hover:bg-red-500/20"
                : "text-white hover:bg-white/10"
            )}
            onClick={handleFavoriteClick}
          >
            <Heart
              className={cn("size-5", isFavorited && "fill-red-500")}
            />
          </Button>
          <div className="absolute bottom-3 left-3 right-3">
            <div className="text-2xl font-bold text-white drop-shadow-lg">
              {formatPrice(property.price)}
            </div>
            {pricePerSqm && (
              <div className="text-sm text-white/80">
                {formatPrice(pricePerSqm)}/m²
              </div>
            )}
          </div>
        </div>

        <div className="p-4 space-y-3">
          <h3 className="line-clamp-2 text-lg leading-tight font-semibold text-foreground">
            {property.title}
          </h3>
          <div className="flex items-center gap-1.5 text-sm text-muted-foreground">
            <MapPin className="size-4 text-primary" />
            <span className="truncate">
              {property.city}
              {property.postalCode && ` (${property.postalCode})`}
            </span>
          </div>

          <div className="flex items-center gap-4 text-sm text-muted-foreground">
            {property.surface && (
              <div className="flex items-center gap-1.5">
                <Ruler className="size-4" />
                <span>{property.surface}m²</span>
              </div>
            )}
            {property.rooms && (
              <div className="flex items-center gap-1.5">
                <Home className="size-4" />
                <span>{property.rooms} pièces</span>
              </div>
            )}
            {property.bedrooms && (
              <div className="flex items-center gap-1.5">
                <Bed className="size-4" />
                <span>{property.bedrooms}</span>
              </div>
            )}
          </div>

          <div className="flex items-center justify-between pt-2 border-t border-[var(--border-subtle)]">
            <div className="flex items-center gap-1.5 text-xs text-muted-foreground">
              <Calendar className="size-3" />
              <span>{formatDate(property.createdAt)}</span>
            </div>
            <div className="flex gap-1.5">
              <ComparisonButton property={property} />
              <FinanceButton property={property} showText={false} />
              <Button size="sm" variant="accent" asChild>
                <Link href={detailUrl}>
                  Voir
                  <ArrowRight className="size-3 ml-1" />
                </Link>
              </Button>
            </div>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="glass-card group overflow-hidden transition-all duration-300 hover:shadow-[0_10px_30px_rgba(0,0,0,0.3),0_0_30px_var(--glow-accent)]">
      <div className="flex">
        <div className="relative aspect-[4/3] w-56 flex-shrink-0 overflow-hidden">
          <SafeImage
            src={property.mainImage ?? property.images[0]}
            alt={property.title}
            fill
            className="object-cover transition-transform duration-500 group-hover:scale-105"
          />
          <div className="absolute inset-0 bg-gradient-to-r from-transparent to-[var(--brand-surface)]" />
          <Button
            variant="ghost"
            size="icon"
            className={cn(
              "absolute top-3 right-3 rounded-xl bg-black/30 backdrop-blur-sm transition-all duration-200",
              isFavorited
                ? "text-red-500 hover:bg-red-500/20"
                : "text-white hover:bg-white/10"
            )}
            onClick={handleFavoriteClick}
          >
            <Heart
              className={cn("size-5", isFavorited && "fill-red-500")}
            />
          </Button>
        </div>

        <div className="flex-1 p-4">
          <div className="mb-3 flex items-start justify-between">
            <div className="flex gap-2">
              <Badge variant="accent">{getTypeLabel(property.type)}</Badge>
              <Badge variant="outline">
                {getCategoryLabel(property.category)}
              </Badge>
            </div>
            <div className="flex items-center gap-1.5 text-xs text-muted-foreground">
              <Calendar className="size-3" />
              <span>{formatDate(property.createdAt)}</span>
            </div>
          </div>

          <h3 className="mb-2 line-clamp-2 text-lg font-semibold text-foreground">
            {property.title}
          </h3>

          <div className="mb-3 flex items-center gap-1.5 text-sm text-muted-foreground">
            <MapPin className="size-4 text-primary" />
            <span>
              {property.city}
              {property.postalCode && ` (${property.postalCode})`}
            </span>
          </div>

          {property.description && (
            <p className="mb-3 line-clamp-2 text-sm text-muted-foreground">
              {property.description}
            </p>
          )}

          <div className="flex items-end justify-between">
            <div>
              <div className="text-2xl font-bold text-gradient-accent">
                {formatPrice(property.price)}
              </div>
              {pricePerSqm && (
                <div className="text-sm text-muted-foreground">
                  {formatPrice(pricePerSqm)}/m²
                </div>
              )}
            </div>

            <div className="flex items-center gap-4 text-sm text-muted-foreground">
              {property.surface && (
                <div className="flex items-center gap-1.5">
                  <Ruler className="size-4" />
                  <span>{property.surface}m²</span>
                </div>
              )}
              {property.rooms && (
                <div className="flex items-center gap-1.5">
                  <Home className="size-4" />
                  <span>{property.rooms} pièces</span>
                </div>
              )}
              {property.bedrooms && (
                <div className="flex items-center gap-1.5">
                  <Bed className="size-4" />
                  <span>{property.bedrooms}</span>
                </div>
              )}
            </div>

            <div className="flex gap-2">
              <ComparisonButton property={property} />
              <FinanceButton property={property} showText={false} />
              {property.url && (
                <Button variant="outline" size="sm" asChild>
                  <Link href={property.url} target="_blank">
                    <ExternalLink className="size-4" />
                  </Link>
                </Button>
              )}
              <Button size="sm" variant="accent" asChild>
                <Link href={detailUrl}>
                  Voir détails
                  <ArrowRight className="size-4 ml-1" />
                </Link>
              </Button>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

"use client";

import { logger } from "@/lib/logger";
import { useState } from "react";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Textarea } from "@/components/ui/textarea";
import {
  Trash2,
  Edit3,
  MapPin,
  Euro,
  Home,
  Save,
  X,
  ExternalLink,
  Star,
  ChevronDown,
  ChevronUp,
} from "lucide-react";
import { DPECard } from "@/components/energy/dpe-card";
import { useDPE } from "@/hooks/use-dpe";
import { deleteFavoriteAction, updateFavoriteAction } from "./favorites.action";
import { cn } from "@/lib/utils";
import type { Favorite, Property } from "@/generated/prisma";

type FavoriteWithProperty = Favorite & {
  property: Property;
};

type FavoriteCardProps = {
  favorite: FavoriteWithProperty;
  onUpdate: () => void;
};

export function FavoriteCard({ favorite, onUpdate }: FavoriteCardProps) {
  const [isLoading, setIsLoading] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [notes, setNotes] = useState(favorite.notes ?? "");
  const [priority, setPriority] = useState<"high" | "medium" | "low">(
    favorite.priority as "high" | "medium" | "low",
  );

  const { isLoading: dpeLoading, enrichFavorite, formatDPEData } = useDPE();
  const [dpeExpanded, setDpeExpanded] = useState(false);

  const dpeData = formatDPEData(favorite);

  const handleRefreshDPE = async () => {
    try {
      await enrichFavorite(favorite.id);
      onUpdate();
    } catch (error) {
      logger.debug("Failed to refresh DPE data:", error);
    }
  };

  const handleDelete = async () => {
    if (
      !confirm(
        `Êtes-vous sûr de vouloir supprimer "${favorite.property.title}" de vos favoris ?`,
      )
    ) {
      return;
    }

    setIsLoading(true);
    try {
      await deleteFavoriteAction(favorite.id);
      onUpdate();
    } catch (error) {
      logger.debug("Erreur lors de la suppression:", error);
    } finally {
      setIsLoading(false);
    }
  };

  const handleSave = async () => {
    setIsLoading(true);
    try {
      await updateFavoriteAction({
        id: favorite.id,
        notes: notes,
        priority: priority,
      });
      setIsEditing(false);
      onUpdate();
    } catch (error) {
      logger.debug("Erreur lors de la sauvegarde:", error);
    } finally {
      setIsLoading(false);
    }
  };

  const handleCancel = () => {
    setIsEditing(false);
    setNotes(favorite.notes ?? "");
    setPriority(favorite.priority as "high" | "medium" | "low");
  };

  const handleStatusChange = async (newStatus: string) => {
    setIsLoading(true);
    try {
      await updateFavoriteAction({
        id: favorite.id,
        status: newStatus as "saved" | "visited" | "contacted" | "rejected",
      });
      onUpdate();
    } catch (error) {
      logger.debug("Erreur lors de la mise à jour:", error);
    } finally {
      setIsLoading(false);
    }
  };

  const getPriorityVariant = (priority: string) => {
    switch (priority) {
      case "high":
        return "destructive";
      case "low":
        return "secondary";
      default:
        return "accent";
    }
  };

  const getStatusLabel = (status: string) => {
    switch (status) {
      case "saved":
        return "Sauvegardé";
      case "visited":
        return "Visité";
      case "contacted":
        return "Contacté";
      case "rejected":
        return "Rejeté";
      default:
        return status;
    }
  };

  return (
    <div className="glass-card overflow-hidden transition-all duration-300 hover:shadow-[0_10px_30px_rgba(0,0,0,0.3)]">
      <div className="p-5 space-y-4">
        <div className="flex items-start justify-between gap-4">
          <div className="min-w-0 flex-1 space-y-3">
            <div className="flex items-center gap-3">
              <h3 className="truncate text-lg font-semibold text-foreground">
                {favorite.property.title}
              </h3>
              <Badge
                variant={getPriorityVariant(favorite.priority)}
                className="flex-shrink-0"
              >
                {favorite.priority === "high" && (
                  <Star className="mr-1 size-3" />
                )}
                {favorite.priority === "high"
                  ? "Priorité haute"
                  : favorite.priority === "low"
                    ? "Priorité basse"
                    : "Normale"}
              </Badge>
            </div>

            <div className="space-y-2">
              <div className="flex items-center gap-2 text-sm text-muted-foreground">
                <MapPin className="size-4 text-primary" />
                {favorite.property.address}, {favorite.property.city} (
                {favorite.property.postalCode})
              </div>

              <div className="flex items-center gap-4 text-sm">
                <div className="flex items-center gap-1.5 text-primary font-semibold">
                  <Euro className="size-4" />
                  {favorite.property.price.toLocaleString("fr-FR")}€
                </div>
                {favorite.property.surface && (
                  <div className="flex items-center gap-1.5 text-muted-foreground">
                    <Home className="size-4" />
                    {favorite.property.surface}m²
                  </div>
                )}
                {favorite.property.rooms && (
                  <div className="text-muted-foreground">
                    {favorite.property.rooms} pièces
                  </div>
                )}
              </div>
            </div>

            <div className="flex flex-wrap items-center gap-2">
              {["saved", "visited", "contacted", "rejected"].map((status) => (
                <button
                  key={status}
                  onClick={async () => handleStatusChange(status)}
                  disabled={isLoading}
                  className={cn(
                    "inline-flex items-center rounded-lg px-3 py-1.5 text-xs font-medium transition-all duration-200",
                    favorite.status === status
                      ? "bg-primary text-primary-foreground shadow-[0_0_15px_var(--glow-accent)]"
                      : "bg-white/5 text-muted-foreground hover:bg-white/10 hover:text-foreground border border-[var(--border-subtle)]",
                  )}
                >
                  {getStatusLabel(status)}
                </button>
              ))}
            </div>
          </div>
        </div>

        <div className="space-y-3">
          <button
            onClick={() => setDpeExpanded(!dpeExpanded)}
            className="flex items-center justify-between w-full px-4 py-3 rounded-xl bg-white/5 hover:bg-white/10 transition-colors duration-200"
          >
            <div className="flex items-center gap-3">
              <span className="text-sm font-medium text-foreground">
                Performance Énergétique
              </span>
              {dpeData.dpeClass && (
                <div
                  className={cn(
                    "size-7 rounded-lg flex items-center justify-center text-xs font-bold text-white",
                    dpeData.dpeClass === "A" || dpeData.dpeClass === "B"
                      ? "bg-emerald-500"
                      : dpeData.dpeClass === "C" || dpeData.dpeClass === "D"
                        ? "bg-yellow-500"
                        : "bg-red-500",
                  )}
                >
                  {dpeData.dpeClass}
                </div>
              )}
              {dpeData.rentalRestrictionRisk && (
                <Badge
                  variant={
                    dpeData.rentalRestrictionRisk === "critical" ||
                    dpeData.rentalRestrictionRisk === "high"
                      ? "destructive"
                      : dpeData.rentalRestrictionRisk === "medium"
                        ? "warning"
                        : "secondary"
                  }
                  className="text-xs"
                >
                  Risque:{" "}
                  {dpeData.rentalRestrictionRisk === "critical"
                    ? "Critique"
                    : dpeData.rentalRestrictionRisk === "high"
                      ? "Élevé"
                      : dpeData.rentalRestrictionRisk === "medium"
                        ? "Moyen"
                        : "Faible"}
                </Badge>
              )}
            </div>
            {dpeExpanded ? (
              <ChevronUp className="size-4 text-muted-foreground" />
            ) : (
              <ChevronDown className="size-4 text-muted-foreground" />
            )}
          </button>

          {dpeExpanded && (
            <div className="animate-fade-in">
              <DPECard
                data={dpeData}
                isLoading={dpeLoading}
                onRefresh={handleRefreshDPE}
                compact
              />
            </div>
          )}
        </div>

        <div className="space-y-2">
          <h4 className="text-sm font-medium text-foreground">
            Notes personnelles
          </h4>
          {isEditing ? (
            <div className="space-y-3">
              <Textarea
                value={notes}
                onChange={(e) => setNotes(e.target.value)}
                placeholder="Ajoutez vos notes sur ce bien..."
                className="min-h-[80px] bg-white/5 border-[var(--border-subtle)]"
                maxLength={500}
              />
              <div className="flex items-center justify-between">
                <p className="text-xs text-muted-foreground">
                  {notes.length}/500 caractères
                </p>
                <div className="flex items-center gap-2">
                  <Button
                    onClick={handleCancel}
                    variant="outline"
                    size="sm"
                    disabled={isLoading}
                  >
                    <X className="mr-1 size-3" />
                    Annuler
                  </Button>
                  <Button
                    onClick={handleSave}
                    size="sm"
                    variant="accent"
                    disabled={isLoading}
                  >
                    <Save className="mr-1 size-3" />
                    Sauvegarder
                  </Button>
                </div>
              </div>
            </div>
          ) : (
            <div>
              {favorite.notes ? (
                <p className="rounded-xl bg-white/5 p-4 text-sm text-muted-foreground whitespace-pre-wrap">
                  {favorite.notes}
                </p>
              ) : (
                <p className="text-sm text-muted-foreground italic">
                  Aucune note pour ce bien
                </p>
              )}
            </div>
          )}
        </div>

        <div className="flex items-center justify-between pt-3 border-t border-[var(--border-subtle)]">
          <div className="text-xs text-muted-foreground">
            Ajouté le{" "}
            {new Date(favorite.createdAt).toLocaleDateString("fr-FR")}
          </div>

          <div className="flex items-center gap-1">
            {favorite.property.sourceUrl && (
              <Button
                asChild
                variant="ghost"
                size="icon"
                className="size-8"
                title="Voir l'annonce"
              >
                <a
                  href={favorite.property.sourceUrl}
                  target="_blank"
                  rel="noopener noreferrer"
                >
                  <ExternalLink className="size-4" />
                </a>
              </Button>
            )}

            <Button
              onClick={() => setIsEditing(!isEditing)}
              variant="ghost"
              size="icon"
              className="size-8"
              disabled={isLoading}
              title="Modifier les notes"
            >
              <Edit3 className="size-4" />
            </Button>

            <Button
              onClick={handleDelete}
              variant="ghost"
              size="icon"
              className="size-8 text-destructive hover:text-destructive hover:bg-destructive/10"
              disabled={isLoading}
              title="Supprimer des favoris"
            >
              <Trash2 className="size-4" />
            </Button>
          </div>
        </div>
      </div>
    </div>
  );
}

