"use client";

import { logger } from "@/lib/logger";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardFooter } from "@/components/ui/card";
import { SafeImage } from "@/components/ui/safe-image";
import type { Property } from "@/lib/moteurimmo/types";
import { useState } from "react";
import { usePathname } from "next/navigation";
import { toggleFavoriteAction } from "@/features/favorites/favorites.action";
import { ComparisonButton } from "@/features/comparison/comparison-button";
import { FinanceButton } from "@/features/finance/finance-button";
import {
  Bed,
  Calendar,
  Heart,
  Home,
  MapPin,
  Ruler,
  ExternalLink,
} from "lucide-react";
import Link from "next/link";

type PropertyCardProps = {
  property: Property;
  view?: "list" | "grid";
  onFavorite?: (property: Property) => void;
  isFavorite?: boolean;
};

export function PropertyCard({
  property,
  view = "list",
  onFavorite,
  isFavorite = false,
}: PropertyCardProps) {
  const pathname = usePathname();
  const isInOrgContext = pathname.startsWith("/orgs/");
  const detailUrl = isInOrgContext
    ? `${pathname}/${property.id}`
    : `/properties/${property.id}`;
  const [isFavorited, setIsFavorited] = useState(isFavorite);
  const [isLoading, setIsLoading] = useState(false);

  const handleFavoriteClick = async () => {
    if (isLoading) return;

    setIsLoading(true);
    try {
      const result = await toggleFavoriteAction(property.uniqueId);
      setIsFavorited(result.isFavorite);
      onFavorite?.(property);
    } catch (error) {
      logger.debug("Erreur lors de la mise à jour du favori:", error);
    } finally {
      setIsLoading(false);
    }
  };
  const formatPrice = (price: number) => {
    return new Intl.NumberFormat("fr-FR", {
      style: "currency",
      currency: "EUR",
      maximumFractionDigits: 0,
    }).format(price);
  };

  const formatDate = (dateString: string) => {
    return new Intl.DateTimeFormat("fr-FR", {
      day: "numeric",
      month: "short",
    }).format(new Date(dateString));
  };

  const getTypeLabel = (type: string) => {
    return type === "sale" ? "Vente" : "Location";
  };

  const getCategoryLabel = (category: string) => {
    const labels = {
      flat: "Appartement",
      house: "Maison",
      land: "Terrain",
      office: "Bureau",
      shop: "Commerce",
      warehouse: "Entrepôt",
      building: "Immeuble",
      "parking/garage/box": "Parking",
    };
    return labels[category as keyof typeof labels] || category;
  };

  const pricePerSqm = property.surface
    ? Math.round(property.price / property.surface)
    : null;

  if (view === "grid") {
    return (
      <Card className="overflow-hidden py-0 transition-shadow hover:shadow-lg">
        {/* Image */}
        <div className="relative aspect-video overflow-hidden rounded-t-lg">
          <SafeImage
            src={property.mainImage ?? property.images[0]}
            alt={property.title}
            fill
            className="object-cover"
          />
          <div className="absolute top-2 left-2 flex gap-1">
            <Badge variant="secondary">{getTypeLabel(property.type)}</Badge>
            <Badge variant="outline">
              {getCategoryLabel(property.category)}
            </Badge>
          </div>
          <Button
            variant="ghost"
            size="icon"
            className="absolute top-2 right-2 bg-white/80 hover:bg-white"
            onClick={handleFavoriteClick}
          >
            <Heart
              className={`h-4 w-4 ${isFavorited ? "fill-red-500 text-red-500" : ""}`}
            />
          </Button>
        </div>

        <CardContent className="p-3">
          <div className="space-y-2">
            <h3 className="line-clamp-2 text-lg leading-tight font-semibold">
              {property.title}
            </h3>
            <div className="text-muted-foreground flex items-center gap-1 text-sm">
              <MapPin className="h-3 w-3" />
              <span className="truncate">
                {property.city}
                {property.postalCode && ` (${property.postalCode})`}
              </span>
            </div>
          </div>

          <div className="mt-3 space-y-2">
            <div className="text-primary text-2xl font-bold">
              {formatPrice(property.price)}
            </div>
            {pricePerSqm && (
              <div className="text-muted-foreground text-sm">
                {formatPrice(pricePerSqm)}/m²
              </div>
            )}
          </div>

          <div className="text-muted-foreground mt-3 flex items-center gap-4 text-sm">
            {property.surface && (
              <div className="flex items-center gap-1">
                <Ruler className="h-3 w-3" />
                <span>{property.surface}m²</span>
              </div>
            )}
            {property.rooms && (
              <div className="flex items-center gap-1">
                <Home className="h-3 w-3" />
                <span>{property.rooms} pièces</span>
              </div>
            )}
            {property.bedrooms && (
              <div className="flex items-center gap-1">
                <Bed className="h-3 w-3" />
                <span>{property.bedrooms}</span>
              </div>
            )}
          </div>
        </CardContent>

        <CardFooter className="flex items-center justify-between px-3 pt-0 pb-3">
          <div className="text-muted-foreground flex items-center gap-1 text-xs">
            <Calendar className="h-3 w-3" />
            <span>{formatDate(property.createdAt)}</span>
          </div>
          <div className="flex gap-2">
            <ComparisonButton property={property} />
            <FinanceButton property={property} showText={false} />
            {property.url && (
              <Button variant="outline" size="sm" asChild>
                <Link href={property.url} target="_blank">
                  <ExternalLink className="h-3 w-3" />
                </Link>
              </Button>
            )}
            <Button size="sm" asChild>
              <Link href={detailUrl}>Voir détails</Link>
            </Button>
          </div>
        </CardFooter>
      </Card>
    );
  }

  // List view
  return (
    <Card className="overflow-hidden py-0 transition-shadow hover:shadow-lg">
      <div className="flex">
        {/* Image */}
        <div className="relative aspect-video w-48 flex-shrink-0 overflow-hidden rounded-l-lg">
          <SafeImage
            src={property.mainImage ?? property.images[0]}
            alt={property.title}
            fill
            className="object-cover"
          />
          <Button
            variant="ghost"
            size="icon"
            className="absolute top-2 right-2 bg-white/80 hover:bg-white"
            onClick={handleFavoriteClick}
          >
            <Heart
              className={`h-4 w-4 ${isFavorited ? "fill-red-500 text-red-500" : ""}`}
            />
          </Button>
        </div>

        {/* Content */}
        <div className="flex-1 p-3">
          <div className="mb-2 flex items-start justify-between">
            <div className="flex gap-2">
              <Badge variant="secondary">{getTypeLabel(property.type)}</Badge>
              <Badge variant="outline">
                {getCategoryLabel(property.category)}
              </Badge>
            </div>
            <div className="text-muted-foreground flex items-center gap-1 text-xs">
              <Calendar className="h-3 w-3" />
              <span>{formatDate(property.createdAt)}</span>
            </div>
          </div>

          <h3 className="mb-2 line-clamp-2 text-lg font-semibold">
            {property.title}
          </h3>

          <div className="text-muted-foreground mb-3 flex items-center gap-1 text-sm">
            <MapPin className="h-3 w-3" />
            <span>
              {property.city}
              {property.postalCode && ` (${property.postalCode})`}
            </span>
          </div>

          {property.description && (
            <p className="text-muted-foreground mb-3 line-clamp-2 text-sm">
              {property.description}
            </p>
          )}

          <div className="flex items-end justify-between">
            <div>
              <div className="text-primary text-2xl font-bold">
                {formatPrice(property.price)}
              </div>
              {pricePerSqm && (
                <div className="text-muted-foreground text-sm">
                  {formatPrice(pricePerSqm)}/m²
                </div>
              )}
            </div>

            <div className="text-muted-foreground flex items-center gap-4 text-sm">
              {property.surface && (
                <div className="flex items-center gap-1">
                  <Ruler className="h-3 w-3" />
                  <span>{property.surface}m²</span>
                </div>
              )}
              {property.rooms && (
                <div className="flex items-center gap-1">
                  <Home className="h-3 w-3" />
                  <span>{property.rooms} pièces</span>
                </div>
              )}
              {property.bedrooms && (
                <div className="flex items-center gap-1">
                  <Bed className="h-3 w-3" />
                  <span>{property.bedrooms}</span>
                </div>
              )}
            </div>

            <div className="flex gap-2">
              <ComparisonButton property={property} />
              <FinanceButton property={property} showText={false} />
              {property.url && (
                <Button variant="outline" size="sm" asChild>
                  <Link href={property.url} target="_blank">
                    <ExternalLink className="h-3 w-3" />
                  </Link>
                </Button>
              )}
              <Button size="sm" asChild>
                <Link href={detailUrl}>Voir détails</Link>
              </Button>
            </div>
          </div>
        </div>
      </div>
    </Card>
  );
}

