import * as React from "react";
import { cn } from "@/lib/utils";

type GradientProgressProps = {
  value: number;
  max?: number;
  label?: string;
  showValue?: boolean;
  size?: "sm" | "md" | "lg";
  variant?: "accent" | "highlight" | "gradient";
  className?: string;
};

function GradientProgress({
  value,
  max = 100,
  label,
  showValue = true,
  size = "md",
  variant = "gradient",
  className,
}: GradientProgressProps) {
  const percentage = Math.min(100, Math.max(0, (value / max) * 100));

  const sizeStyles = {
    sm: "h-1.5",
    md: "h-2.5",
    lg: "h-4",
  };

  const gradientStyles = {
    accent: "bg-[var(--brand-accent)]",
    highlight: "bg-[var(--brand-highlight)]",
    gradient:
      "bg-gradient-to-r from-[var(--brand-accent)] to-[var(--brand-highlight)]",
  };

  const glowStyles = {
    accent: "shadow-[0_0_20px_var(--glow-accent)]",
    highlight: "shadow-[0_0_20px_var(--glow-highlight)]",
    gradient:
      "shadow-[0_0_20px_var(--glow-accent),0_0_20px_var(--glow-highlight)]",
  };

  return (
    <div className={cn("space-y-2", className)}>
      {(label || showValue) && (
        <div className="flex items-center justify-between text-sm">
          {label && <span className="text-muted-foreground">{label}</span>}
          {showValue && (
            <span className="font-medium text-foreground">
              {Math.round(percentage)}%
            </span>
          )}
        </div>
      )}
      <div
        className={cn(
          "overflow-hidden rounded-full bg-white/5",
          sizeStyles[size],
        )}
      >
        <div
          className={cn(
            "h-full rounded-full transition-all duration-500 ease-out",
            gradientStyles[variant],
            glowStyles[variant],
          )}
          style={{ width: `${percentage}%` }}
        />
      </div>
    </div>
  );
}

type CircularProgressProps = {
  value: number;
  max?: number;
  size?: number;
  strokeWidth?: number;
  variant?: "accent" | "highlight" | "gradient";
  showValue?: boolean;
  label?: string;
  className?: string;
};

function CircularProgress({
  value,
  max = 100,
  size = 120,
  strokeWidth = 8,
  variant = "gradient",
  showValue = true,
  label,
  className,
}: CircularProgressProps) {
  const percentage = Math.min(100, Math.max(0, (value / max) * 100));
  const radius = (size - strokeWidth) / 2;
  const circumference = radius * 2 * Math.PI;
  const offset = circumference - (percentage / 100) * circumference;

  const gradientId = React.useId();

  return (
    <div
      className={cn("relative inline-flex items-center justify-center", className)}
      style={{ width: size, height: size }}
    >
      <svg width={size} height={size} className="-rotate-90">
        <defs>
          <linearGradient id={gradientId} x1="0%" y1="0%" x2="100%" y2="0%">
            <stop offset="0%" stopColor="var(--brand-accent)" />
            <stop offset="100%" stopColor="var(--brand-highlight)" />
          </linearGradient>
        </defs>
        <circle
          cx={size / 2}
          cy={size / 2}
          r={radius}
          fill="none"
          stroke="rgba(255,255,255,0.05)"
          strokeWidth={strokeWidth}
        />
        <circle
          cx={size / 2}
          cy={size / 2}
          r={radius}
          fill="none"
          stroke={
            variant === "gradient"
              ? `url(#${gradientId})`
              : variant === "accent"
                ? "var(--brand-accent)"
                : "var(--brand-highlight)"
          }
          strokeWidth={strokeWidth}
          strokeDasharray={circumference}
          strokeDashoffset={offset}
          strokeLinecap="round"
          className="transition-all duration-700 ease-out"
          style={{
            filter:
              variant === "accent"
                ? "drop-shadow(0 0 10px var(--glow-accent))"
                : variant === "highlight"
                  ? "drop-shadow(0 0 10px var(--glow-highlight))"
                  : "drop-shadow(0 0 10px var(--glow-accent)) drop-shadow(0 0 10px var(--glow-highlight))",
          }}
        />
      </svg>
      <div className="absolute flex flex-col items-center">
        {showValue && (
          <span className="text-2xl font-bold text-foreground">
            {Math.round(percentage)}%
          </span>
        )}
        {label && (
          <span className="text-xs text-muted-foreground">{label}</span>
        )}
      </div>
    </div>
  );
}

export { GradientProgress, CircularProgress };

