import { Typography } from "@/components/nowts/typography";
import { cn } from "@/lib/utils";
import type { ComponentPropsWithoutRef, ReactNode } from "react";

type SectionLayoutProps = {
  size?: "sm" | "base" | "lg";
  variant?: "default" | "card" | "primary" | "invert" | "image" | "glass";
  containerClassName?: string;
  sectionTitle?: string;
  title?: ReactNode;
  subtitle?: string;
} & ComponentPropsWithoutRef<"div">;

export const SectionLayout = ({
  size = "base",
  variant = "default",
  className,
  containerClassName,
  sectionTitle,
  title,
  subtitle,
  children,
  ...props
}: SectionLayoutProps) => {
  return (
    <div
      className={cn(
        {
          "bg-transparent text-foreground": variant === "default",
          "bg-[var(--brand-surface)] text-foreground": variant === "card",
          "bg-primary text-primary-foreground": variant === "primary",
          "bg-foreground text-background": variant === "invert",
          "text-foreground backdrop-blur-sm backdrop-brightness-75":
            variant === "image",
          "glass text-foreground": variant === "glass",
        },
        containerClassName,
      )}
      {...props}
    >
      <div
        className={cn(
          "m-auto px-4 py-20 lg:py-28",
          {
            "max-w-4xl": size === "sm",
            "max-w-5xl": size === "base",
            "max-w-6xl": size === "lg",
          },
          className,
        )}
      >
        {(sectionTitle ?? title ?? subtitle) && (
          <div className="mb-12 text-center lg:mb-16">
            {sectionTitle && (
              <Typography className="text-primary mb-4 text-sm font-semibold uppercase tracking-wider">
                {sectionTitle}
              </Typography>
            )}
            {title && (
              <Typography
                variant="h2"
                className="text-3xl font-bold tracking-tight text-foreground sm:text-4xl lg:text-5xl"
              >
                {title}
              </Typography>
            )}
            {subtitle && (
              <Typography
                variant="large"
                className="text-muted-foreground mx-auto mt-4 max-w-2xl text-lg"
              >
                {subtitle}
              </Typography>
            )}
          </div>
        )}
        {children}
      </div>
    </div>
  );
};
